import pytest
from wordfreq import count_words

def test_count_words():
    assert count_words('hello world hello') == {'hello': 2, 'world': 1}
    assert count_words('one two three one TWO') == {'one': 2, 'two': 2, 'three': 1}
    assert count_words('') == {}

if __name__ == '__main__':
    pytest.main(['-v', __file__])

